    const primary=(t.actions||[]).find(a=>a.primary),secondary=(t.actions||[]).find(a=>!a.primary);
    const free=companion.freeTime||t.freeWindows?.[0],conflict=companion.risk||t.conflicts?.[0],freeSuggestions=(free?.suggestions||[]).filter(item=>{const n=String(item?.name||item?.title||'').trim();return n&&!/^(unbenannter ort|unbekannter ort|unknown place)$/i.test(n)}).slice(0,2);const freeFallback=free?.fallback||(!freeSuggestions.length?(free?.minutes<20?{title:'Kurze Pause',text:'Für einen weiteren Ort ist die Zeit zu knapp.'}:free?.minutes<=45?{title:'Etwas Luft im Plan',text:'Die Zeit eignet sich für eine Pause oder einen kurzen Spaziergang.'}:free?.minutes<=90?{title:'Zeit für eine entspannte Pause',text:'Aktuell passt kein weiterer fester Ort sinnvoll dazwischen.'}:{title:'Noch viel Zeit bis zum nächsten Programmpunkt',text:'Aktuell wurde kein zusätzlicher Ort gefunden, der wirklich gut in euren Plan passt.'}):null);
