function entityToPlace(entity){const p=entity?.place||{},tp=entity?.tripPlace||{},raw=p.raw_provider_data||{},routeData=p.attributes?.routeData||raw.routeData||null;return window.LuviaPlaceDomain.normalize({id:p.id,tripId:tp.trip_id,primaryType:p.primary_type||'custom',roles:p.roles||[],name:tp.custom_name||p.name,address:p.address,latitude:p.latitude,longitude:p.longitude,source:p.source||'google_places',sourceId:p.source_id||p.provider_place_id,lifecycle:tp.lifecycle_status||tp.status||'saved',metadata:{tripPlaceId:tp.id,providerPlaceId:p.provider_place_id,plannedDate:tp.planned_date,plannedTime:tp.planned_time,isFavorite:tp.is_favorite,routeData,rawProviderData:raw,place:p,tripPlace:tp,extension:entity.extension||null}});}
