    if(!editable(node))return;const entry=contract().reads.getEntry(node.dataset.entryId),controls=document.createElement('nav');controls.className='lvjt-move-controls';controls.setAttribute('aria-label',`Zeit verschieben: ${entry.title}`);
    controls.innerHTML=`<span aria-hidden="true">⠿</span><button type="button" data-group-select="${escapeHtml(entry.id)}" aria-pressed="false">Für gemeinsamen Weg auswählen</button><button type="button" data-move-minutes="-15" aria-label="15 Minuten früher">↑</button><button type="button" data-move-minutes="15" aria-label="15 Minuten später">↓</button><button type="button" data-move-time>Tag und Uhrzeit</button>`;
