  const offline=selected?globalThis.LuviaJourneyOfflinePack?.status?.(trip,selected.date):null,pulse=ordered.some(day=>(day.openGaps||[]).length||day.conflicts?.length)?' is-opportunity':'',recoveries=contract().reads.removalRecoveries?.({tripId:String(trip?.id||trip?.tripId||'')})||[],visitRecoveries=safeVisitRecoveries(),connectionRecoveries=contract().reads.connectionRecoveries?.({tripId:String(trip?.id||trip?.tripId||'')})||[];
