  content.addEventListener('submit',async event=>{const form=event.target.closest('[data-visit-edit]');if(!form||busy)return;event.preventDefault();busy=true;const submit=event.submitter,status=form.querySelector('[data-visit-status]'),data=new FormData(form);submit.disabled=true;status.textContent='Aktuelle Revision wird geprüft und die Korrektur beim Places Owner gespeichert …';try{const arrived=new Date(`${data.get('date')}T${data.get('time')}:00`);if(Number.isNaN(arrived.getTime()))throw new Error('Bitte ein gültiges Datum und eine gültige Uhrzeit angeben.');await places.commands.updateVisit(visit.id,{confirmed:true,operationId:crypto.randomUUID(),expectedRevision:visit.revision||entry.sourceRevision,arrivedAt:arrived.toISOString(),durationSeconds:Number(data.get('duration'))*60,leftAt:null});await refresh('visit-owner-updated');globalThis.LuviaUIKit?.toast?.('Besuchszeit beim Places Owner korrigiert.',{type:'success'})}catch(error){busy=false;submit.disabled=false;status.textContent=error?.message||'Die Besuchskorrektur konnte nicht sicher gespeichert werden.'}});
