  root.querySelectorAll('[data-journey-restore-visit]').forEach(button=>button.addEventListener('click',async()=>{if(button.disabled)return;button.disabled=true;try{await openVisitRestore(button.dataset.journeyRestoreVisit)}catch(error){button.disabled=false;globalThis.LuviaUIKit?.toast?.(error?.message||'Der Besuch konnte nicht wiederhergestellt werden.',{type:'error'})}}));
