function defaults(row={}){const date=row.start_at?new Date(row.start_at):null;return{date:date&&!Number.isNaN(date.getTime())?date.toISOString().slice(0,10):'',time:date&&!Number.isNaN(date.getTime())?date.toTimeString().slice(0,5):'',partySize:Number(row.party_size||1)}}
