function diagnostics(){return Object.freeze({version:VERSION,owner:'booking-consumer-surface',domainTruth:false,source:'booking.v1',visibleNavigation:false,actions:['manage-external','modify-if-supported','cancel-if-supported','reply-if-thread'],policy:'booking.lifecycle-policy.v1',sheet:'overlay-host.v1'})}
