function enrichDistance(place){if(!place||typeof place!=='object')return place;const context=window.LuviaTravelContext?.snapshot?.()||{};const hasGps=Boolean(context.location&&Number.isFinite(Number(context.location.latitude))&&Number.isFinite(Number(context.location.longitude)));const distance=hasGps?window.LuviaTravelContext?.distanceTo?.(place.location||{latitude:place.latitude,longitude:place.longitude}):null;return{...place,distanceMeters:Number.isFinite(distance)?distance:null,distanceSource:Number.isFinite(distance)?'gps':'unavailable'};}
async function search(query,options={}){state.searches++;try{const response=await window.LuviaPlaceEntities.searchPlaces({...options,type:'restaurant',query});if(Array.isArray(response?.data?.places)){response.data.places=response.data.places.map(enrichDistance);const quick=response.data.places.slice();queueMicrotask(async()=>{try{let enriched=quick;if(window.LuviaRecommendations){const recs=await window.LuviaRecommendations.get({module:'restaurants',tripId:tripId(options.tripId),intent:options.intent||'for-you',candidates:quick,persist:options.persistRecommendations!==false,limit:quick.length,context:{partySize:options.partySize||null,hasBaby:Boolean(options.hasBaby)}});const byId=new Map(recs.map(r=>[r.entityId,r]));enriched=quick.map(place=>{const r=byId.get(String(place.id||place.providerPlaceId||''));return r?{...place,matchScore:r.score,recommendation:r}:place})}if(window.LuviaRestaurantIntelligence)enriched=await window.LuviaRestaurantIntelligence.enhance(enriched,{intent:options.intent||'for-you'});window.dispatchEvent(new CustomEvent('luvia:restaurant-search-enriched',{detail:{query,places:enriched}}))}catch(_){}})}return response}catch(error){state.failures++;state.lastError={code:error.code,message:error.message};throw error}}
