  [STATUS.RUNNING]:Object.freeze([STATUS.SUCCEEDED,STATUS.FAILED,STATUS.OUTCOME_UNKNOWN]),
  [STATUS.FAILED]:Object.freeze([STATUS.RUNNING,STATUS.CANCELLED,STATUS.COMPENSATING]),
