/* ===== core/ai/ai-memory-service.js ===== */
(() => {
  'use strict';

  const VERSION = '1.1.0';
  const listeners = new Set();
  let state = {signals:[], loaded:false, loading:false, error:null, updatedAt:null};

  const clone = value => value == null ? value : JSON.parse(JSON.stringify(value));
  const userId = () => window.LuviaIdentityContractV1?.getViewerIdentity?.()?.userId || null;
  const tripId = () => window.LuviaTripContractV1?.getContext?.()?.tripId || null;
  const text = value => String(value ?? '').trim();
  const values = value => [...new Set((Array.isArray(value) ? value : [value]).map(text).filter(Boolean))];

  const CATEGORY_TARGETS = Object.freeze({
    dietary:{key:'dietaryPreferences', type:'array'},
    diet:{key:'dietaryPreferences', type:'array'},
    dietary_preferences:{key:'dietaryPreferences', type:'array'},
    travel_interests:{key:'travelInterests', type:'array'},
    interests:{key:'travelInterests', type:'array'},
    travel_styles:{key:'travelStyles', type:'array'},
    styles:{key:'travelStyles', type:'array'},
    activities:{key:'activityPreferences', type:'array'},
    activity:{key:'activityPreferences', type:'array'},
    entertainment:{key:'entertainmentPreferences', type:'array'},
    dining:{key:'diningPreferences', type:'array'},
    mobility:{key:'mobilityPreferences', type:'array'},
    atmosphere:{key:'atmospherePreferences', type:'array'},
    travel_pace:{key:'travelPace', type:'scalar'},
    pace:{key:'travelPace', type:'scalar'},
    budget:{key:'budgetPreference', type:'scalar'},
    family:{key:'familyPreferences', type:'needs'},
    accessibility:{key:'accessibilityPreferences', type:'needs'}
  });

  function snapshot(){
    return Object.freeze({...state, signals:clone(state.signals)});
  }

  function emit(reason){
    const value = snapshot();
    listeners.forEach(listener => {
      try { listener(value, reason); } catch (error) { console.warn('[LuviaAIMemory]', error); }
    });
    window.dispatchEvent(new CustomEvent('luvia:ai-memory-changed', {detail:{reason, snapshot:value}}));
    return value;
  }

  async function load({force=false}={}){
    if (state.loading) return snapshot();
    if (state.loaded && !force) return snapshot();
    const uid = userId();
    if (!uid) {
      state = {signals:[], loaded:true, loading:false, error:null, updatedAt:new Date().toISOString()};
      return emit('anonymous');
    }
    state = {...state, loading:true, error:null};
    emit('loading');
    try {
      const client = await window.LuviaSupabaseService.start();
      const {data,error} = await client.from('ai_learning_signals')
        .select('*')
        .eq('user_id', uid)
        .neq('status', 'dismissed')
        .order('last_observed_at', {ascending:false})
        .limit(100);
      if (error) throw error;
      state = {signals:data || [], loaded:true, loading:false, error:null, updatedAt:new Date().toISOString()};
      return emit('loaded');
    } catch (error) {
      state = {...state, loaded:true, loading:false, error:error?.message || String(error)};
      emit('load-error');
      return snapshot();
    }
  }

  async function recordSignal(signal={}, options={}){
    const uid = userId();
    if (!uid) throw new Error('AUTH_REQUIRED');
    const client = await window.LuviaSupabaseService.start();
    const params = {
      p_trip_id:options.tripId || tripId() || null,
      p_scope_key:signal.scopeKey || options.scopeKey || 'global',
      p_signal_key:text(signal.signalKey || signal.signal_key),
      p_category:text(signal.category || 'general').toLowerCase(),
      p_value:signal.value || {},
      p_confidence:Number(signal.confidence ?? .5),
      p_source_summary:signal.sourceSummary || {evidence:signal.evidence || '', capability:options.capability || 'memory.extract'},
      p_status:signal.status || 'inferred'
    };
    if (!params.p_signal_key) throw new Error('SIGNAL_KEY_REQUIRED');
    const {data,error} = await client.rpc('luvia_record_ai_learning_signal', params);
    if (error) throw error;
    await load({force:true});
    return data;
  }

  async function updateSignalStatus(signalOrId, status){
    const uid = userId();
    if (!uid) throw new Error('AUTH_REQUIRED');
    if (!['inferred','confirmed','dismissed'].includes(status)) throw new Error('AI_SIGNAL_STATUS_INVALID');
    const id = typeof signalOrId === 'string' ? signalOrId : signalOrId?.id;
    if (!id) throw new Error('AI_SIGNAL_ID_REQUIRED');
    const client = await window.LuviaSupabaseService.start();
    const {data,error} = await client.from('ai_learning_signals')
      .update({status, updated_at:new Date().toISOString()})
      .eq('id', id)
      .eq('user_id', uid)
      .select('*')
      .maybeSingle();
    if (error) throw error;
    await load({force:true});
    return data;
  }

  function preferencePatch(signal={}){
    const category = text(signal.category).toLowerCase();
    const target = CATEGORY_TARGETS[category];
    const label = text(signal.value?.label || signal.value?.value || signal.label);
    if (!target || !label) throw new Error('AI_SIGNAL_NOT_CONFIRMABLE');
    const current = window.LuviaIdentityContractV1?.getPreferences?.('self') || {};
    if (target.type === 'array') return {[target.key]:values([...(current[target.key] || []), label])};
    if (target.type === 'scalar') return {[target.key]:label};
    const currentObject = current[target.key] && typeof current[target.key] === 'object' ? current[target.key] : {};
    return {[target.key]:{...currentObject, needs:values([...(currentObject.needs || []), label])}};
  }

  async function confirmSignal(signal={}){
    const patch = preferencePatch(signal);
    const command = window.LuviaIdentityContractV1?.commands?.updatePreferences;
    if (typeof command !== 'function') throw new Error('IDENTITY_PREFERENCE_COMMAND_UNAVAILABLE');
    await command(patch, {reason:'ai-signal-confirmed'});
    const updated = await updateSignalStatus(signal, 'confirmed');
    await recordInteraction({
      capability:'memory.confirm',
      eventType:'signal.confirmed',
      entityType:'ai_learning_signal',
      entityId:signal.id,
      payload:{signalKey:signal.signal_key || signal.signalKey, category:signal.category}
    });
    return updated;
  }

  async function dismissSignal(signal={}){
    const updated = await updateSignalStatus(signal, 'dismissed');
    await recordInteraction({
      capability:'memory.review',
      eventType:'signal.dismissed',
      entityType:'ai_learning_signal',
      entityId:signal.id,
      payload:{signalKey:signal.signal_key || signal.signalKey, category:signal.category}
    });
    return updated;
  }

  async function recordInteraction(event={}){
    const uid = userId();
    if (!uid) return null;
    const client = await window.LuviaSupabaseService.start();
    const row = {
      user_id:uid,
      trip_id:event.tripId || tripId() || null,
      capability:event.capability || 'unknown',
      event_type:event.eventType || event.type || 'observed',
      entity_type:event.entityType || null,
      entity_id:event.entityId ? String(event.entityId) : null,
      payload:window.LuviaAIPolicy.sanitize(event.payload || {})
    };
    const {data,error} = await client.from('ai_interaction_events').insert(row).select().maybeSingle();
    if (error) throw error;
    return data;
  }

  async function learnFromEvent(event={}){
    try {
      await recordInteraction(event);
      const result = await window.LuviaIntelligenceContractV1?.run?.('memory.extract', {input:event}, {fallback:true});
      for (const signal of result?.data?.signals || []) await recordSignal(signal, {capability:'memory.extract'});
      return result;
    } catch (error) {
      console.warn('[LuviaAIMemory] Lernereignis konnte nicht verarbeitet werden.', error);
      return null;
    }
  }

  function subscribe(listener){
    listeners.add(listener);
    listener(snapshot(), 'subscribe');
    return () => listeners.delete(listener);
  }

  window.addEventListener('luvia:recommendations-changed', event => {
    const detail = event.detail || {};
    if (/^decision\.(accepted|rejected|converted)$/.test(detail.name || '')) {
      learnFromEvent({
        capability:'recommendation.learning',
        eventType:detail.name,
        entityType:detail.recommendation?.entityType,
        entityId:detail.recommendation?.entityId,
        payload:{reason:detail.reason || null, action:detail.action || null, module:detail.recommendation?.module || null}
      });
    }
  });
  window.addEventListener('luvia:place-collection-changed', event => {
    const detail = event.detail || {};
    if (['favorite-added','favorite-removed','favorites-cleared'].includes(detail.action)) {
      learnFromEvent({
        capability:'place.learning',
        eventType:detail.action,
        entityType:detail.placeType || 'place',
        entityId:detail.providerPlaceId || detail.tripPlaceId || null,
        payload:{isFavorite:detail.isFavorite, placeType:detail.placeType}
      });
    }
  });
  window.addEventListener('luvia:user-preferences-changed', () => load({force:true}).catch(() => {}));
  window.addEventListener('luvia:auth-changed', () => load({force:true}).catch(() => {}));
  window.addEventListener('luvia:ai-ready', () => load().catch(() => {}), {once:true});

  window.LuviaAIMemory = Object.freeze({
    version:VERSION,
    load,
    snapshot,
    recordSignal,
    updateSignalStatus,
    confirmSignal,
    dismissSignal,
    recordInteraction,
    learnFromEvent,
    subscribe,
    diagnostics:() => ({version:VERSION, ...snapshot(), source:'supabase.ai_learning_signals', profileMutation:'explicit-confirmation-only'})
  });
})();

;

/* ===== core/ai/ai-command-proposal-service.js ===== */
(() => {
  'use strict';
  const VERSION='1.1.0';
  const listeners=new Set();
  const clone=v=>v==null?v:JSON.parse(JSON.stringify(v));
  const userId=()=>window.LuviaIdentityContractV1?.getViewerIdentity?.()?.userId||null;
  const tripId=()=>window.LuviaTripContractV1?.getContext?.()?.tripId||null;
  const emit=(reason,proposal)=>{listeners.forEach(fn=>{try{fn(clone(proposal),reason)}catch{}});window.dispatchEvent(new CustomEvent('luvia:ai-proposal-changed',{detail:{reason,proposal:clone(proposal)}}))};
  async function create(input={}){
    const uid=userId();if(!uid)throw new Error('AUTH_REQUIRED');
    const row={user_id:uid,trip_id:input.tripId||tripId()||null,capability:input.capability||'timeline.propose',action_type:input.actionType||'timeline.batch',action_payload:window.LuviaAIPolicy.sanitize(input.actionPayload||input.payload||{}),explanation:String(input.explanation||''),status:'draft'};
    const client=await window.LuviaSupabaseService.start();const {data,error}=await client.from('ai_action_proposals').insert(row).select().single();if(error)throw error;emit('created',data);return data;
  }
  async function setStatus(proposal,status,errorText=null){
    if(!proposal?.id)return proposal;
    const client=await window.LuviaSupabaseService.start();
    const patch={status,updated_at:new Date().toISOString()};
    if(['accepted','rejected'].includes(status))patch.decided_at=new Date().toISOString();
    if(status==='executed')patch.executed_at=new Date().toISOString();
    if(errorText)patch.error_text=String(errorText).slice(0,1000);
    const {data,error}=await client.from('ai_action_proposals').update(patch).eq('id',proposal.id).select().single();if(error)throw error;emit(status,data);return data;
  }
  function eventFromChange(change={}){return{id:change.eventId||crypto.randomUUID(),tripId:tripId(),title:change.title||'Reisemoment',date:change.date,time:change.time,durationMinutes:Number(change.durationMinutes||90),entityType:'ai-proposed',source:{ai:true,reason:change.reason||''}}}
  async function execute(proposal,{confirmed=false}={}){
    if(!confirmed)throw new Error('AI_CONFIRMATION_REQUIRED');
    const payload=proposal.action_payload||proposal.actionPayload||{};
    const changes=Array.isArray(payload.changes)?payload.changes:[];
    await setStatus(proposal,'accepted');
    try{
      for(const change of changes){
        if(change.action==='remove')window.LuviaScheduleIntelligence?.removeEvent?.(change.eventId,{tripId:tripId()});
        else if(change.action==='update'){
          const current=window.LuviaScheduleIntelligence?.snapshot?.()?.events?.find?.(event=>String(event.id)===String(change.eventId));
          window.LuviaScheduleIntelligence?.upsertEvent?.({...current,...eventFromChange(change),id:change.eventId||current?.id});
        }else if(change.action==='add')window.LuviaScheduleIntelligence?.upsertEvent?.(eventFromChange(change));
      }
      const done=await setStatus(proposal,'executed');
      window.LuviaUIKit?.toast?.('Die bestätigten Reiseänderungen wurden übernommen.',{type:'success'});return done;
    }catch(error){await setStatus(proposal,'failed',error?.message||String(error)).catch(()=>{});throw error}
  }
  function modal(proposal={}){
    const payload=proposal.action_payload||proposal.actionPayload||{};const changes=payload.changes||[];
    const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    return new Promise(resolve=>{
      const ui=LuviaUI;if(!ui?.mount)throw new Error('Overlay Host v1 ist noch nicht bereit.');const content=document.createElement('section');content.className='luv-ai-proposal';
      content.innerHTML=`<span class="luv-ai-kicker">Luvia denkt mit – du entscheidest</span><h2>${esc(payload.title||'Vorschlag für euren Reisetag')}</h2><p>${esc(proposal.explanation||payload.explanation||'Diese Änderungen werden erst nach deiner Bestätigung gespeichert.')}</p><div class="luv-ai-proposal-list">${changes.map(change=>`<article><b>${esc(change.action==='remove'?'Entfernen':change.action==='update'?'Ändern':'Einplanen')}</b><span>${esc(change.date||'')} ${esc(change.time||'')} · ${esc(change.title||change.eventId||'Eintrag')}</span><small>${esc(change.reason||'')}</small></article>`).join('')||'<article><span>Keine ausführbaren Änderungen vorhanden.</span></article>'}</div><div class="luv-ai-proposal-actions"><button type="button" data-ai-reject>Nicht übernehmen</button><button type="button" data-ai-confirm ${changes.length?'':'disabled'}>Änderungen übernehmen</button></div>`;
      let settled=false,mounted=null;const finish=value=>{if(settled)return;settled=true;mounted.close(value?'confirm':'reject');resolve(value)};
      mounted=ui.mount({name:'intelligence.command-proposal',kind:'dialog',content,className:'luv-ai-proposal-overlay',initialFocus:changes.length?'[data-ai-confirm]':'[data-ai-reject]',onClose:()=>{if(!settled){settled=true;resolve(false)}}});
      mounted.overlay.querySelector('[data-ai-reject]').onclick=()=>finish(false);
      mounted.overlay.querySelector('[data-ai-confirm]').onclick=()=>finish(true);
    });
  }
  async function present(input={}){
    const proposal=input.id?input:await create(input);
    const confirmed=await modal(proposal);
    if(!confirmed){await setStatus(proposal,'rejected').catch(()=>{});return{ok:false,confirmed:false,proposal}}
    const executed=await execute(proposal,{confirmed:true});return{ok:true,confirmed:true,proposal:executed};
  }
  function subscribe(fn){listeners.add(fn);return()=>listeners.delete(fn)}
  window.LuviaAIProposals=Object.freeze({version:VERSION,create,present,execute,setStatus,subscribe,diagnostics:()=>({version:VERSION,confirmationRequired:true,allowedActions:['timeline.add','timeline.update','timeline.remove']})});
})();

;

/* ===== core/ai/ai-orchestrator.js ===== */
(() => {'use strict';const VERSION='4.19.1';const MAX_STEPS=5;const clone=v=>v==null?v:JSON.parse(JSON.stringify(v));async function executeToolCalls(calls=[],capability){const out=[];for(const call of calls.slice(0,8)){try{const data=await window.LuviaAITools.invoke(call.name,call.arguments||{});out.push({id:call.id||crypto.randomUUID(),name:call.name,ok:true,data})}catch(error){out.push({id:call.id||crypto.randomUUID(),name:call.name,ok:false,error:error.message||String(error)})}}return out}async function run(capability,input={},options={}){const trace=[],toolResults=[];for(let step=0;step<MAX_STEPS;step++){const response=await window.LuviaOpenAIProvider.invoke('brain.orchestrate',{capability,tier:options.tier,input,context:options.context||{},tools:window.LuviaAITools.list(),toolResults,step});const data=response.data?.result||response.data||{};trace.push({step,kind:data.kind||'final',toolCalls:(data.toolCalls||[]).map(c=>c.name)});if(data.kind!=='tool_calls'||!data.toolCalls?.length)return{ok:true,data:data.result||data,meta:{...(response.meta||{}),orchestrated:true,steps:step+1,trace}};toolResults.push(...await executeToolCalls(data.toolCalls,capability))}throw new Error('AI_ORCHESTRATION_STEP_LIMIT')}function diagnostics(){return{version:VERSION,maxSteps:MAX_STEPS,toolCount:window.LuviaAITools?.list?.().length||0,domainCount:window.LuviaAIDomains?.list?.().length||0}}window.LuviaAIOrchestrator=Object.freeze({version:VERSION,run,diagnostics});})();

;

