 if(destination?.name&&destination.latitude!=null&&destination.longitude!=null){places.push({place:{id:`destination:${activeTrip.id||activeTrip.tripId||'active'}`,name:destination.name,tripPlaceId:null,coordinates:{latitude:Number(destination.latitude),longitude:Number(destination.longitude)}},synthetic:true})}
 return places.map(entry=>{const p=entry.place,pos=p.coordinates||p.location||{};const ds=points.map(m=>distance(m,{latitude:Number(pos.latitude??pos.lat),longitude:Number(pos.longitude??pos.lng)})).filter(Number.isFinite);return{place:p,synthetic:entry.synthetic,distanceMeters:ds.length?Math.min(...ds):null}}).filter(x=>x.distanceMeters!=null&&x.distanceMeters<=(x.synthetic?5000:750)).sort((a,b)=>a.distanceMeters-b.distanceMeters).slice(0,3);
