 const evidence=[{id:`cluster:${c.id}`,kind:'media_cluster',confidence:1,payload:{clusterId:c.id,title:c.title,kind:c.kind,count:items.length,startAt:c.start_at,endAt:c.end_at}},{id:`time:${c.id}`,kind:'capture_window',confidence:.95,payload:{startAt:c.start_at,endAt:c.end_at,dayKey:String(c.start_at||'').slice(0,10),durationMinutes:summary.durationMinutes}},...items.slice(0,12).map(m=>({id:`media:${m.id}`,kind:'media_capture',confidence:m.captureEvidenceAvailable ? .98 : .72,payload:{mediaId:m.id,capturedAt:m.capturedAt,latitude:m.latitude,longitude:m.longitude,participantId:m.participantId,resolvedLocation:m.resolvedLocation||null}})),...candidates.map(x=>({id:`place:${x.place.id}`,kind:x.synthetic?'nearby_destination':'nearby_place',confidence:Math.max(.55,1-x.distanceMeters/1000),payload:{placeId:x.place.id,name:x.place.name,distanceMeters:Math.round(x.distanceMeters),synthetic:Boolean(x.synthetic)}}))];
