async function analyze(clusterId){const p=await propose(clusterId);try{await persist(p)}catch(error){console.warn('[LuviaAIMemoryBridge] Vorschlag wurde ohne Persistenz geliefert.',error)}return p}
const diagnostics=()=>{const contract=runtime.LuviaMediaContractV1||runtime.LuviaMediaContract,mediaReady=Boolean(contract?.reads?.listMedia&&contract?.commands?.media?.linkPlace);return{service:'ai-memory-bridge',version:VERSION,build:BUILD,status:'active',ok:Boolean(mediaReady&&runtime.LuviaMediaClustering),checkedAt:new Date().toISOString(),durationMs:0,dependencies:{mediaContract:mediaReady,clustering:Boolean(runtime.LuviaMediaClustering),timeline:Boolean(runtime.LuviaJourneyContractV1),placeLifecycle:Boolean(runtime.LuviaPlaceLifecycleService),evidence:Boolean(runtime.LuviaAIEvidence)},checks:{smallContext:true,humanReadableEvidence:true,evidenceRequired:true,manualConfirmation:true,boundedActions:true,photoMemoryTimeline:true,noFreeWrites:true},failedChecks:[],warnings:[]}}
