window.LuviaRestaurantsV2={getData:trip=>modelFor(trip),openPlace:openPlaceFromExternal,search:contract=>{const i=window.LuviaModules?.instances?.get(MODULE_ID);return i&&contract?runEntitySearch(i,contract.query,{discoveryContract:contract}):false},openEditor:()=>{const i=window.LuviaModules?.instances?.get(MODULE_ID);if(i)editor(i)},resetDemo:()=>false};
