  try{const geography=window.LuviaPlacesSpatialExperience.tripGeography(state.trip),request={tripId:tripId(),trip:state.trip,type:'accommodation',category:'accommodation',query:state.query,text:state.query,userQuery:QUICK.some(item=>item[2]===state.query)?'':state.query,destination:geography,destinationContext:geography,profilePreferences:{},includedTypes:hotelSubtype()?[hotelSubtype()]:[],strictPlaceType:hotelSubtype(),accessibleOnly:Boolean(state.options.accessibleOnly),maxDistanceMeters:3000,candidateLimit:80,limit:80,maxResultCount:80,strictDestination:true,providers:['auto'],fastPath:true,parallelFastQueries:false,fastQueryLimit:1,queryVariantLimit:1,providerTimeoutMs:6500,minRating:state.options.minRating,minUserRatingCount:state.options.minUserRatingCount||0,sortBy:state.options.sortBy||'relevance',openNow:Boolean(state.options.openNow)},reader=window.LuviaPlacesSpatialExperience.viewportSearchWithContinuity||window.LuviaPlacesSpatialExperience.viewportSearch,r=state.activeViewport&&keepMap?{places:await reader({...state.activeViewport,...request,includedType:hotelSubtype()||'lodging',continuityEligible:!hotelSubtype()&&hotelFilterCount()===0},()=>token===state.searchToken)}:await window.LuviaPlacesContractV1.reads.recommend(request);if(token!==state.searchToken)return false;state.results=filteredHotelRows(r?.places||[]);state.searchMap=new Map(state.results.map(p=>[providerId(p),p]));state.searchStatus=state.results.length?'ready':'empty'}
