    const filterButton=event.target.closest('[data-hotel-filter]');
    if(filterButton){const key=filterButton.dataset.hotelFilter;if(key==='rating')state.options.minRating=state.options.minRating?null:4.5;if(key==='reviews')state.options.minUserRatingCount=state.options.minUserRatingCount?0:100;if(key==='accessible')state.options.accessibleOnly=!state.options.accessibleOnly;if(key==='sort')state.options.sortBy=state.options.sortBy==='rating'?'relevance':'rating';state.filterOpen=true;refreshHotelFilters();await search(state.filter,state.options);return}
