const state={root:null,trip:null,query:'Sehenswürdigkeiten und Aktivitäten',filter:'Entdecken',options:{},results:[],entities:[],searchMap:new Map(),routeCache:new Map(),loading:false,error:null,visibleCount:6};
const esc=v=>window.LuviaPlaceExperience?.esc?.(v)||String(v??'');
const tripContract=()=>window.LuviaTripContractV1||window.LuviaTripContract||null;
