const fmtDistance=m=>{m=Number(m);if(!Number.isFinite(m))return null;return m<1000?`${Math.round(m/50)*50} m`:`${(m/1000).toFixed(m<10000?1:0).replace('.',',')} km`};
function normalized(p,l={}){return {...p,id:p.id||p.placeId||providerId(p),placeId:p.id||p.placeId,primaryType:'attraction',symbol:'✨',lifecycle:l.status||p.lifecycleStatus||'discovered',address:p.shortAddress||p.formattedAddress||p.formatted_address||p.address||'',description:p.editorialSummary||p.description||'',matchScore:p.matchScore||p.match_score||Math.max(50,Math.min(96,Math.round((Number(p.rating)||3.8)*17))),metadata:{...(p.metadata||{}),tripPlaceId:l.id}}}
async function photoUris(photos,max=6){const out=[];for(const photo of (photos||[]).slice(0,max)){try{if(photo.uri||photo.url){out.push({uri:photo.uri||photo.url});continue}const r=await window.LuviaPlaces.photo(photo.name,{maxWidthPx:1200,maxHeightPx:900});if(r?.data?.photoUri)out.push({uri:r.data.photoUri})}catch{}}return out}
async function hydrate(places){await Promise.all((places||[]).slice(0,20).map(async p=>{if(!p._cardPhotoUri&&p.photos?.length){const x=await photoUris(p.photos,1);if(x[0])p._cardPhotoUri=x[0].uri}const origin=window.LuviaTravelContext?.snapshot?.()?.location;if(!origin||!p.location||!window.LuviaPlaces?.route)return;const key=providerId(p);try{let route=state.routeCache.get(key);if(!route){route=(await window.LuviaPlaces.route(origin,p.location))?.data||null;if(route)state.routeCache.set(key,route)}if(route?.walk?.distanceMeters||route?.drive?.distanceMeters){const meters=route.walk?.distanceMeters||route.drive?.distanceMeters;p.route=route;p.gpsDistanceMeters=meters;p.distanceMeters=meters}}catch{}}))}
