async function hydrateFavoriteMedia(){const favorites=state.entities.filter(e=>link(e).is_favorite===true).filter(e=>providerId(place(e))&&!place(e)._cardPhotoUri).slice(0,6);if(!favorites.length)return;let changed=false;for(const entity of favorites){const p=place(entity),id=providerId(p);try{const prepared=await window.LuviaPlaceDetails?.prepare?.(id,{regionCode:'DE',photoLimit:1});const detail=prepared?.place||prepared?.response?.data?.place||{};Object.assign(p,detail,{providerPlaceId:id,primaryType:'attraction'});const photos=prepared?.photos?.length?prepared.photos:await photoUris((detail.photos||[]).slice(0,1),1);if(photos[0]?.uri){p._cardPhotoUri=photos[0].uri;changed=true}state.searchMap.set(id,p)}catch(_){}}if(changed&&state.root?.isConnected)render()}
function scheduledItems(){return (window.LuviaTripPlaceData?.dateEntries?.('attraction')||[]).map(e=>({id:e.id,tripPlaceId:e.tripPlaceId,dataKey:e.dataKey,title:e.title,time:`${new Date(e.startAt).toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit',year:'numeric'})} · ${new Date(e.startAt).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})} Uhr`,entry:e}))}
function timelineAction(l){return window.LuviaPlaceUIActions.actionButtons({favorite:Boolean(l?.is_favorite),planned:Boolean(ext({tripPlace:l||{}}).starts_at),favoriteAttr:l?.id?'data-fav':'data-import-detail',planAttr:'data-plan-attraction'})}
