function savedCard(e){const p=normalized(place(e),link(e)),l=link(e),intel=intelligence(p,e);const rating=p.rating?`${Number(p.rating).toFixed(1).replace('.',',')} ★ · ${p.userRatingCount||0} Bewertungen`:'';p.description=[rating,p.description].filter(Boolean).join(' · ');return window.LuviaPlaceUI.card(p,{className:'rv2-search-card rv2-search-card-intelligent',openAttribute:`data-place-card-open="saved:${esc(l.id)}"`,media:p._cardPhotoUri?`<div class="rv2-card-media"><img src="${esc(p._cardPhotoUri)}" alt="${esc(p.name)}" loading="eager" fetchpriority="high"></div>`:`<div class="rv2-card-media is-placeholder"><span>📸</span></div>`,intelligence:intel,actions:`<button type="button" class="rv2-detail-button primary" data-place-card-open="saved:${esc(l.id)}">Warum passt das?</button>${window.LuviaPlaceCollections.favoriteButton({placeType:'photo_spot',providerPlaceId:providerId(p),tripPlaceId:l.id,isFavorite:Boolean(l.is_favorite)})}`})}
async function hydrateFavoriteMedia(){const favorites=state.entities.filter(e=>link(e).is_favorite===true).filter(e=>providerId(place(e))&&!place(e)._cardPhotoUri).slice(0,6);if(!favorites.length)return;let changed=false;for(const entity of favorites){const p=place(entity),id=providerId(p);try{const prepared=await window.LuviaPlaceDetails?.prepare?.(id,{regionCode:'DE',photoLimit:1});const detail=prepared?.place||prepared?.response?.data?.place||{};Object.assign(p,detail,{providerPlaceId:id,primaryType:'photo_spot'});const photos=prepared?.photos?.length?prepared.photos:await photoUris((detail.photos||[]).slice(0,1),1);if(photos[0]?.uri){p._cardPhotoUri=photos[0].uri;changed=true}state.searchMap.set(id,p)}catch(_){}}if(changed&&state.root?.isConnected)render()}
function scheduledItems(){return (window.LuviaTripPlaceData?.dateEntries?.('photo_spot')||[]).map(e=>({id:e.id,tripPlaceId:e.tripPlaceId,dataKey:e.dataKey,title:e.title,time:`${new Date(e.startAt).toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit',year:'numeric'})} · ${new Date(e.startAt).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})} Uhr`,entry:e}))}
