function openPlanning(p,l,e){return window.LuviaPlaceUIActions.openTimelineDialog({type:'photo_spot',tripId:tripId(),place:p,entity:e,tripPlace:l,importEntity:async()=>importOne(providerId(p),{silent:true,status:'planned',favorite:false}),onSaved:async()=>{await load()}})}
