    const evidence=place.features?.servesVegetarianFood===true?'Vegetarische Optionen sind hinterlegt.':place.accessibilityOptions?.wheelchairAccessibleEntrance===true?'Ein rollstuhlgerechter Eingang ist bestätigt.':'';
