    return [positive,...(person.unknowns||[]).slice(0,1)].filter(Boolean).join(' ').replace(/\bstroller\b/gi,'Kinderwagen-Zugang').replace(/\bvegetarian\b/gi,'Vegetarische Auswahl').replace(/\bwheelchair\b/gi,'Rollstuhlzugang');
