  async function loadMembers(tripId){const c=client||window.LuviaSupabaseService?.getClient?.();if(!c||!tripId)return[];const r=await c.rpc('luvia_list_trip_members',{p_trip_id:tripId});if(r.error)throw r.error;members=r.data||[];emit();return members}
