    const renderDay=day=>{const count=day.entries?.length||0,date=displayDate(day.date),label=day.label&&!/^\d{4}-\d{2}-\d{2}/.test(day.label)?[day.label,date].filter(Boolean).join(' · '):date||day.label||'Reisetag';return`<article class="lvx-day-card"><header><span>${esc(label)}</span><b>${esc(count)} ${count===1?'Moment':'Momente'}</b></header><div>${(day.entries||[]).map(entry=>`<div class="lvx-day-entry"><p><time>${esc(time(entry.startAt)||'Offen')}</time><strong>${esc(entry.title)}</strong></p>${entry.actions?.length?`<div class="lvx-rich-actions">${entry.actions.map(offer=>ownerActionButton(offer,entry)).join('')}</div>`:''}</div>`).join('')||'<p><strong>Noch keine Reisemomente geplant.</strong></p>'}</div>${day.conflictCount?`<em>${esc(day.conflictCount)} Zeitkonflikt${day.conflictCount===1?'':'e'} prüfen</em>`:''}</article>`};
