    const placeMapMarkup=result=>`<div class="lvx-place-map" data-place-map-shell data-map-state="loading" data-ai-shared-discovery="${esc(result.evidence?.sharedDiscovery?.id||'')}" data-ai-provider-read-count="${esc(result.evidence?.sharedDiscovery?.providerReadCount??'')}"><div class="lvx-place-map-engine" data-ai-place-map data-map-renderer="maplibre" role="group" aria-label="Karte für ${esc(result.title||'passende Orte')}"></div><small class="lvx-place-map-status" data-place-map-status role="status" aria-live="polite">Die Karte wird aus den bestätigten Ortsangaben aufgebaut …</small></div>`;
