  const fmt=v=>v?new Date(v+'T12:00:00').toLocaleDateString('de-DE'):'Offen';
  const initials=p=>(p.displayName||p.email||'L').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();
