        if (bookDeleteButton) bookDeleteButton.disabled = !selectedBookElement?.matches("[data-book-removable]");
        if (bookObjectTools) bookObjectTools.hidden = !selectedBookElement;
        syncBookTransformTools();
        syncBookPhotoStyleTools();
